"stat_cert_val": {
tr: "SHGM Lisansı",
en: "DGCA Commercial License"
},
"iha2_blurb_p1": {
tr: "İHA-2 Ticari Drone Ehliyeti Eğitimi, kalkış ağırlığı 25kg ile 150kg arasındaki büyük ölçekli endüstriyel platformları yönetme yetkisi verir. Büyük ölçekli tarımsal ilaçlama, ağır kargo/lojistik taşımacılığı, sınır güvenliği, arama-kurtarma koordinasyonu ve savunma sanayii Ar-Ge projeleri gibi kritik operasyonların anahtarıdır.",
en: "UAV-2 Commercial Drone License Training grants authority to operate large-scale industrial platforms from 25kg to 150kg takeoff weight. It is the key to executing heavy agricultural spraying, large cargo logistics, border security surveillance, and defense R&D missions."
},
"iha2_blurb_p2": {
tr: "Bu ileri düzey eğitimde; profesyonel otopilot sistemleri, görev planlama yazılımları, gelişmiş aviyonikler ve acil durum kurtarma prosedürleri detaylıca incelenir ve geniş saha uçuş test sahalarında gerçek uçuş pratikleriyle tamamlanır.",
en: "This advanced course covers professional autopilot suites, mission planning software, complex avionics, and emergency recovery procedures, validated through hands-on flight training in dedicated open airspace testing zones."
},
"iha3_blurb_p1": {
tr: "İHA-3 Ticari Drone Ehliyeti Eğitimi, kalkış ağırlığı 150kg ve üzeri olan askeri ve devasa endüstriyel insansız hava araçlarının operasyonlarını kapsar. Stratejik kargo taşımacılığı, sınır gözetleme sistemleri, askeri savunma sanayii projeleri ve kıtalararası uçuş yapabilen İHA platformlarının kontrolü bu lisans ile sağlanır.",
en: "UAV-3 Commercial Drone License Training covers massive military and strategic industrial unmanned aerial systems with a takeoff weight of 150kg and above. This license governs operations of long-range heavy cargo logistics, defense intelligence missions, and strategic surveillance."
},
"iha3_blurb_p2": {
tr: "Program; gelişmiş aerodinamik, ileri seyrüsefer sistemleri, türbin veya büyük motor yapıları ve yer kontrol istasyonları yazılımları gibi üst düzey havacılık eğitimlerini simülatör ve test sahalarındaki pratik uygulamalarla birleştirir.",
en: "The curriculum blends high-level aeronautics, advanced navigation suites, turbine or large piston engine maintenance, and ground control station software, completed with high-fidelity simulators and tactical field test flights."
},
